PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS schema_migrations (version TEXT PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS roles (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, label TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS permissions (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, label TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS role_permissions (role_id INTEGER NOT NULL REFERENCES roles(id), permission_id INTEGER NOT NULL REFERENCES permissions(id), PRIMARY KEY(role_id, permission_id));
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, role_id INTEGER NOT NULL REFERENCES roles(id), name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, phone TEXT, password_hash TEXT NOT NULL, is_active INTEGER NOT NULL DEFAULT 1, must_change_password INTEGER NOT NULL DEFAULT 0, failed_logins INTEGER NOT NULL DEFAULT 0, locked_until TEXT, last_login_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS residents (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER UNIQUE REFERENCES users(id), nik TEXT UNIQUE, full_name TEXT NOT NULL, birth_place TEXT, birth_date TEXT, address TEXT, rt TEXT, rw TEXT, verified_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS resident_verifications (id INTEGER PRIMARY KEY AUTOINCREMENT, resident_id INTEGER NOT NULL REFERENCES residents(id), verifier_id INTEGER NOT NULL REFERENCES users(id), status TEXT NOT NULL, notes TEXT, verified_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS letter_types (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, code TEXT NOT NULL UNIQUE, description TEXT, requirements TEXT NOT NULL DEFAULT '[]', requires_identity INTEGER NOT NULL DEFAULT 1, requires_approval INTEGER NOT NULL DEFAULT 1, sla_days INTEGER NOT NULL DEFAULT 5, is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS letter_templates (id INTEGER PRIMARY KEY AUTOINCREMENT, letter_type_id INTEGER NOT NULL REFERENCES letter_types(id), name TEXT NOT NULL, body_html TEXT NOT NULL, is_active INTEGER NOT NULL DEFAULT 1, version INTEGER NOT NULL DEFAULT 1, created_by INTEGER REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS template_versions (id INTEGER PRIMARY KEY AUTOINCREMENT, template_id INTEGER NOT NULL REFERENCES letter_templates(id), version INTEGER NOT NULL, body_html TEXT NOT NULL, changed_by INTEGER REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(template_id, version));
CREATE TABLE IF NOT EXISTS letter_fields (id INTEGER PRIMARY KEY AUTOINCREMENT, letter_type_id INTEGER NOT NULL REFERENCES letter_types(id), field_name TEXT NOT NULL, label TEXT NOT NULL, field_type TEXT NOT NULL DEFAULT 'text', is_required INTEGER NOT NULL DEFAULT 0, options TEXT, position INTEGER NOT NULL DEFAULT 0, UNIQUE(letter_type_id, field_name));
CREATE TABLE IF NOT EXISTS letter_applications (id INTEGER PRIMARY KEY AUTOINCREMENT, tracking_token TEXT NOT NULL UNIQUE, resident_id INTEGER NOT NULL REFERENCES residents(id), letter_type_id INTEGER NOT NULL REFERENCES letter_types(id), status TEXT NOT NULL DEFAULT 'pending_review', payload TEXT NOT NULL DEFAULT '{}', register_id INTEGER, rejection_reason TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS letter_application_documents (id INTEGER PRIMARY KEY AUTOINCREMENT, application_id INTEGER NOT NULL REFERENCES letter_applications(id), storage_path TEXT NOT NULL, original_name TEXT NOT NULL, mime_type TEXT NOT NULL, uploaded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS letter_registers (id INTEGER PRIMARY KEY AUTOINCREMENT, application_id INTEGER NOT NULL UNIQUE REFERENCES letter_applications(id), register_number TEXT NOT NULL UNIQUE, official_number TEXT UNIQUE, period TEXT NOT NULL, sequence_number INTEGER NOT NULL, assigned_by INTEGER NOT NULL REFERENCES users(id), assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, status TEXT NOT NULL DEFAULT 'reserved', UNIQUE(period, sequence_number));
CREATE TABLE IF NOT EXISTS letters (id INTEGER PRIMARY KEY AUTOINCREMENT, application_id INTEGER NOT NULL UNIQUE REFERENCES letter_applications(id), template_id INTEGER NOT NULL REFERENCES letter_templates(id), status TEXT NOT NULL DEFAULT 'draft', snapshot_html TEXT NOT NULL, snapshot_data TEXT NOT NULL, verification_token TEXT UNIQUE, issued_at TEXT, issued_by INTEGER REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS letter_versions (id INTEGER PRIMARY KEY AUTOINCREMENT, letter_id INTEGER NOT NULL REFERENCES letters(id), version INTEGER NOT NULL, reason TEXT NOT NULL, snapshot_html TEXT NOT NULL, snapshot_data TEXT NOT NULL, changed_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(letter_id, version));
CREATE TABLE IF NOT EXISTS letter_approvals (id INTEGER PRIMARY KEY AUTOINCREMENT, application_id INTEGER NOT NULL REFERENCES letter_applications(id), approver_id INTEGER NOT NULL REFERENCES users(id), decision TEXT NOT NULL, notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS letter_signatures (id INTEGER PRIMARY KEY AUTOINCREMENT, letter_id INTEGER NOT NULL REFERENCES letters(id), file_path TEXT NOT NULL, uploaded_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS letter_verification_tokens (id INTEGER PRIMARY KEY AUTOINCREMENT, letter_id INTEGER NOT NULL REFERENCES letters(id), token_hash TEXT NOT NULL UNIQUE, revoked_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS letter_status_histories (id INTEGER PRIMARY KEY AUTOINCREMENT, application_id INTEGER NOT NULL REFERENCES letter_applications(id), actor_id INTEGER REFERENCES users(id), old_status TEXT, new_status TEXT NOT NULL, note TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id), application_id INTEGER REFERENCES letter_applications(id), message TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pickup_confirmations (id INTEGER PRIMARY KEY AUTOINCREMENT, application_id INTEGER NOT NULL UNIQUE REFERENCES letter_applications(id), pickup_code_hash TEXT NOT NULL, handed_by INTEGER NOT NULL REFERENCES users(id), picked_up_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, received_by TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, actor_id INTEGER REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id INTEGER, details TEXT NOT NULL DEFAULT '{}', ip_address TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS system_settings (setting_key TEXT PRIMARY KEY, setting_value TEXT NOT NULL, updated_by INTEGER REFERENCES users(id), updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ai_usage_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, actor_id INTEGER NOT NULL REFERENCES users(id), action TEXT NOT NULL, data_redacted INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS register_counters (id INTEGER PRIMARY KEY AUTOINCREMENT, letter_type_id INTEGER NOT NULL REFERENCES letter_types(id), period TEXT NOT NULL, next_number INTEGER NOT NULL, UNIQUE(letter_type_id, period));
CREATE INDEX IF NOT EXISTS idx_applications_status ON letter_applications(status, created_at);
CREATE INDEX IF NOT EXISTS idx_applications_resident ON letter_applications(resident_id, created_at);
CREATE INDEX IF NOT EXISTS idx_histories_application ON letter_status_histories(application_id, created_at);
CREATE INDEX IF NOT EXISTS idx_audit_actor ON audit_logs(actor_id, created_at);